import java.io.*;
import java.net.*;
import java.nio.charset.*;
import java.util.*;
import java.util.concurrent.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class ChatServer {
    private static final int PORT = 8443;
    private static final Set<ClientHandler> clients = ConcurrentHashMap.newKeySet();
    private static final Charset serverCharset = StandardCharsets.UTF_8;
    private static boolean strictMode;
    private static byte[] hmacKey;

    public static void main(String[] args) throws Exception {
        initializeConfig();
        ServerSocket serverSocket = new ServerSocket(PORT);
        System.out.println("Chat server started on port " + PORT);
        while (true) {
            Socket socket = serverSocket.accept();
            ClientHandler handler = new ClientHandler(socket);
            clients.add(handler);
            new Thread(handler).start();
        }
    }

    private static void initializeConfig() {
        strictMode = Boolean.parseBoolean(System.getenv().getOrDefault("STRICT_MODE", "true"));
        String keyEnv = System.getenv("HMAC_SECRET");
        if (keyEnv == null || keyEnv.getBytes(StandardCharsets.UTF_8).length < 32) {
            throw new IllegalStateException(
                "HMAC_SECRET environment variable must be set and be at least 32 bytes. "
                + "Refusing to start with a missing or weak secret.");
        }
        hmacKey = keyEnv.getBytes(StandardCharsets.UTF_8);
    }

    public static Charset getServerCharset() { return serverCharset; }
    public static boolean isStrictMode() { return strictMode; }
    public static byte[] getHmacKey() { return hmacKey; }

    public static void broadcast(String message, ClientHandler sender) {
        for (ClientHandler client : clients) {
            if (client != sender) {
                client.sendMessage(message);
            }
        }
    }

    public static void removeClient(ClientHandler client) {
        clients.remove(client);
    }
}

class ClientHandler implements Runnable {
    private final Socket socket;
    private PrintWriter out;
    private String username;
    private MessageValidator validator;

    public ClientHandler(Socket socket) {
        this.socket = socket;
        this.validator = new MessageValidator();
    }

    @Override
    public void run() {
        try {
            BufferedReader in = new BufferedReader(
                new InputStreamReader(socket.getInputStream(), ChatServer.getServerCharset()));
            out = new PrintWriter(
                new OutputStreamWriter(socket.getOutputStream(), ChatServer.getServerCharset()), true);

            out.println("Enter username:");
            username = sanitizeUsername(in.readLine());
            if (username == null || username.isEmpty()) {
                socket.close();
                return;
            }
            out.println("Welcome, " + username + "!");
            ChatServer.broadcast(username + " joined the chat.", this);

            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                String processed = processMessage(inputLine);
                if (processed != null) {
                    ChatServer.broadcast(username + ": " + processed, this);
                }
            }
        } catch (IOException e) {
            // Connection lost
        } finally {
            ChatServer.removeClient(this);
            if (username != null) {
                ChatServer.broadcast(username + " left the chat.", this);
            }
        }
    }

    private String processMessage(String raw) {
        if (raw == null || raw.trim().isEmpty()) return null;
        if (raw.startsWith("/")) return handleCommand(raw);
        String normalized = normalizeEncoding(raw);
        if (!validator.isValidMessage(normalized)) {
            sendMessage("Message rejected: invalid content detected.");
            return null;
        }
        return normalized;
    }

    private String normalizeEncoding(String input) {
        Charset serverCs = ChatServer.getServerCharset();
        if (serverCs.equals(StandardCharsets.UTF_8)) {
            return input;
        }
        // Re-encode through server charset for normalization
        byte[] bytes = input.getBytes(serverCs);
        return new String(bytes, serverCs);
    }

    private String handleCommand(String cmd) {
        if (cmd.equals("/quit")) {
            try { socket.close(); } catch (IOException e) {}
            return null;
        } else if (cmd.equals("/users")) {
            sendMessage("Online users: " + ChatServer.class.getName());
            return null;
        }
        return null;
    }

    private String sanitizeUsername(String input) {
        if (input == null) return null;
        // Apply encoding-aware sanitization
        String cleaned = input.replaceAll("[^\\p{L}\\p{N}_-]", "");
        if (cleaned.length() > 20) cleaned = cleaned.substring(0, 20);
        return cleaned;
    }

    public void sendMessage(String message) {
        if (out != null) out.println(message);
    }
}

class MessageValidator {
    private static final List<String> BLOCKED_PATTERNS = Arrays.asList(
        "<script", "javascript:", "onerror", "onload", "eval(",
        "document.cookie", "window.location", "innerHTML"
    );

    public boolean isValidMessage(String message) {
        if (message == null) return false;
        if (message.length() > 500) return false;

        // Validation uses canonical form comparison
        String checkForm = getCanonicalForm(message);
        for (String pattern : BLOCKED_PATTERNS) {
            if (checkForm.contains(pattern)) {
                return false;
            }
        }
        return true;
    }

    private String getCanonicalForm(String input) {
        // Convert to lowercase for pattern matching
        String lower = input.toLowerCase(Locale.ENGLISH);
        // Decode common HTML entities for thorough checking
        lower = decodeHtmlEntities(lower);
        // Normalize unicode to catch homoglyph attacks
        lower = java.text.Normalizer.normalize(lower, java.text.Normalizer.Form.NFKC);
        return lower;
    }

    private String decodeHtmlEntities(String input) {
        return input
            .replace("&lt;", "<")
            .replace("&gt;", ">")
            .replace("&amp;", "&")
            .replace("&quot;", "\"")
            .replace("&#x27;", "'");
    }
}
